UPDATE questions SET stem_html='<p>Wharton, House of Mirth: Lily ''could be keenly sensitive to a scene which was the fitting background of her own sensations.'' [Underlined:] The landscape outspread below her seemed an enlargement of her present mood... What is the function of the underlined sentence?</p>', choices_json='[{"id": "A", "content": "It creates a detailed image of the physical setting."}, {"id": "B", "content": "It establishes an internal conflict."}, {"id": "C", "content": "It makes an assertion the next sentence expands on."}, {"id": "D", "content": "It illustrates an idea introduced in the previous sentence."}]', explanation_html=NULL, stem_text='Wharton, House of Mirth: Lily ''could be keenly sensitive to a scene which was the fitting background of her own sensations.'' [Underlined:] The landscape outspread below her seemed an enlargement of her present mood... What is the function of the underlined sentence?' WHERE id='pt10_rw_m2_q06';
UPDATE questions SET stem_html='<p>Studies found little electoral cost to austerity, yet some European governments recently suffered for it. Huebscher et al. attribute this to a timing practice not followed in these cases. What is the function of the underlined sentence?</p>', choices_json='[{"id": "A", "content": "Explains a lab-vs-real-world discrepancy attributed to studies not using real-world data."}, {"id": "B", "content": "Identifies a conflict between research findings and recent events, later explained as a complicating factor in the data."}, {"id": "C", "content": "Presents a long-standing divergence attributed to different researchers using different data."}, {"id": "D", "content": "Describes a recent exception attributed to researchers underestimating data inconsistencies."}]', explanation_html=NULL, stem_text='Studies found little electoral cost to austerity, yet some European governments recently suffered for it. Huebscher et al. attribute this to a timing practice not followed in these cases. What is the function of the underlined sentence?' WHERE id='pt10_rw_m2_q07';
UPDATE questions SET stem_html='<p>Adam Smith''s ''invisible hand'' metaphor was *putatively* used to model self-interest producing aggregate benefit; it was actually used once, narrowly, then elevated to a paradigm by 20th-century economists. What is the main idea?</p>', choices_json='[{"id": "A", "content": "The metaphor was ignored until economists realized it anticipated their views."}, {"id": "B", "content": "Economists gave it undue significance, but it''s still a useful model."}, {"id": "C", "content": "It was interpreted as a self-interest model but intended as a mercantilism critique."}, {"id": "D", "content": "The metaphor''s reputation isn''t due to its importance in Smith''s work but to later economists promoting it for their own ends."}]', explanation_html=NULL, stem_text='Adam Smith''s ''invisible hand'' metaphor was *putatively* used to model self-interest producing aggregate benefit; it was actually used once, narrowly, then elevated to a paradigm by 20th-century economists. What is the main idea?' WHERE id='pt10_rw_m2_q08';
UPDATE questions SET stem_html='<figure class="image"><table><caption>Employment by Sector in France and the United States, 1800&ndash;2012 (% of total employment)</caption><tr><th>Year</th><th>Agriculture in France</th><th>Manufacturing in France</th><th>Services in France</th><th>Agriculture in US</th><th>Manufacturing in US</th><th>Services in US</th></tr><tr><td>1800</td><td>64</td><td>22</td><td>14</td><td>68</td><td>18</td><td>13</td></tr><tr><td>1900</td><td>43</td><td>29</td><td>28</td><td>41</td><td>28</td><td>31</td></tr><tr><td>1950</td><td>32</td><td>33</td><td>35</td><td>14</td><td>33</td><td>53</td></tr><tr><td>2012</td><td>3</td><td>21</td><td>76</td><td>2</td><td>18</td><td>80</td></tr></table><figcaption style="font-size:12px">Rows in table may not add up to 100 due to rounding.</figcaption></figure><p>Over the past two hundred years, the percentage of the population employed in the agricultural sector has declined in both France and the United States, while employment in the service sector (which includes jobs in retail, consulting, real estate, etc.) has risen. However, this transition happened at very different rates in the two countries. This can be seen most clearly by comparing the employment by sector in both countries in ______</p><p>Which choice most effectively uses data from the table to complete the statement?</p>', choices_json='[{"id": "A", "content": "1900 with 1950"}, {"id": "B", "content": "1800 with 2012"}, {"id": "C", "content": "1900 with 2012"}, {"id": "D", "content": "1800 with 1900"}]', explanation_html=NULL, stem_text='Employment by Sector in France and the United States, 1800&ndash;2012 (% of total employment)YearAgriculture in FranceManufacturing in FranceServices in FranceAgriculture in USManufacturing in USServices in US18006422146818131900432928412831195032333514335320123217621880Rows in table may not add up to 100 due to rounding.Over the past two hundred years, the percentage of the population employed in the agricultural sector has declined in both France and the United States, while employment in the service sector (which includes jobs in retail, consulting, real estate, etc.) has risen. However, this transition happened at very different rates in the two countries. This can be seen most clearly by comparing the employment by sector in both countries in ______
Which choice most effectively uses data from the table to complete the statement?' WHERE id='pt10_rw_m2_q12';
UPDATE questions SET stem_html='<p>Sweet potato is native to South America but cultivated in Polynesia before any sea voyages existed between them; DNA shows divergence 100,000+ years ago, Polynesia peopled only in the last 3,000 years. What did the team conclude?</p>', choices_json='[{"id": "A", "content": "Cultivation in Polynesia predates South America."}, {"id": "B", "content": "Polynesians acquired it from South Americans within the last 3,000 years."}, {"id": "C", "content": "Human activity likely played no role in introducing it to Polynesia."}, {"id": "D", "content": "Polynesian varieties descend from a domesticated South American variety."}]', explanation_html=NULL, stem_text='Sweet potato is native to South America but cultivated in Polynesia before any sea voyages existed between them; DNA shows divergence 100,000+ years ago, Polynesia peopled only in the last 3,000 years. What did the team conclude?' WHERE id='pt10_rw_m2_q14';
