UPDATE questions SET stem_html='<p>$220 for the first 2 hours, plus an hourly fee after. Total cost for 5 hours = $400. Which f(x) gives total cost for x>=2 hours? 60x+100 / 60x+220 / 80x / 80x+220</p>', choices_json='[{"id": "A", "content": "f(x)=60x+100"}, {"id": "B", "content": "f(x)=60x+220"}, {"id": "C", "content": "f(x)=80x"}, {"id": "D", "content": "f(x)=80x+220"}]', explanation_html=NULL, stem_text='$220 for the first 2 hours, plus an hourly fee after. Total cost for 5 hours = $400. Which f(x) gives total cost for x>=2 hours? 60x+100 / 60x+220 / 80x / 80x+220' WHERE id='pt10_math_m2_q22';
UPDATE questions SET stem_html='<p>Some economic historians ______ that late nineteenth- and early twentieth-century households in the United States experienced an economy of scale when it came to food purchases&mdash;they assumed that large households spent less on food per person than did small households. Economist Trevon Logan showed, however, that a close look at the available data disproves this supposition.</p><p><strong>Which choice completes the text with the most logical and precise word or phrase?</strong></p>', choices_json='[{"id": "A", "content": "surmised"}, {"id": "B", "content": "contrived"}, {"id": "C", "content": "questioned"}, {"id": "D", "content": "regretted"}]', explanation_html=NULL, stem_text='Some economic historians ______ that late nineteenth- and early twentieth-century households in the United States experienced an economy of scale when it came to food purchases&mdash;they assumed that large households spent less on food per person than did small households. Economist Trevon Logan showed, however, that a close look at the available data disproves this supposition.
Which choice completes the text with the most logical and precise word or phrase?' WHERE id='pt4_rw_m1_q5';
UPDATE questions SET stem_html='<p><em>Adapted from Jack London''s 1903 novel</em> The Call of the Wild. <em>Buck is a sled dog living with John Thornton in Yukon, Canada.</em></p><p>Thornton alone held [Buck]. The rest of mankind was as nothing. Chance travellers might praise or pet him; but he was cold under it all, and from a too demonstrative man he would get up and walk away. When Thornton''s partners, Hans and Pete, arrived on the long-expected raft, Buck refused to notice them till he learned they were close to Thornton; after that he tolerated them in a passive sort of way, accepting favors from them as though he favored them by accepting.</p><p><strong>Which choice best states the main idea of the text?</strong></p>', choices_json='[{"id": "A", "content": "Buck has become less social since he began living with Thornton."}, {"id": "B", "content": "Buck mistrusts humans and does his best to avoid them."}, {"id": "C", "content": "Buck has been especially well liked by most of Thornton''s friends."}, {"id": "D", "content": "Buck holds Thornton in higher regard than any other person."}]', explanation_html=NULL, stem_text='Adapted from Jack London''s 1903 novel The Call of the Wild. Buck is a sled dog living with John Thornton in Yukon, Canada.
Thornton alone held [Buck]. The rest of mankind was as nothing. Chance travellers might praise or pet him; but he was cold under it all, and from a too demonstrative man he would get up and walk away. When Thornton''s partners, Hans and Pete, arrived on the long-expected raft, Buck refused to notice them till he learned they were close to Thornton; after that he tolerated them in a passive sort of way, accepting favors from them as though he favored them by accepting.
Which choice best states the main idea of the text?' WHERE id='pt4_rw_m1_q9';
UPDATE questions SET stem_html='<p>A model created by biologist Luis Valente predicts that the rate of speciation&mdash;the rate at which new species form&mdash;on an isolated island located approximately 5,000 kilometers from the nearest mainland ______ triple the rate of speciation on an island only 500 kilometers from the mainland.</p><p><strong>Which choice completes the text so that it conforms to the conventions of Standard English?</strong></p>', choices_json='[{"id": "A", "content": "being"}, {"id": "B", "content": "to be"}, {"id": "C", "content": "to have been"}, {"id": "D", "content": "will be"}]', explanation_html=NULL, stem_text='A model created by biologist Luis Valente predicts that the rate of speciation&mdash;the rate at which new species form&mdash;on an isolated island located approximately 5,000 kilometers from the nearest mainland ______ triple the rate of speciation on an island only 500 kilometers from the mainland.
